const isChatOpen = !!variables['e8d5dc85-33c9-4772-9027-684024bf3b5b'] && variables['b0d14c6e-49a9-4e32-887d-e55a3d9ac4bf'] === 'chat';
if (!isChatOpen) return;

function findBubbles() {
  return Array.from(document.querySelectorAll('span, div')).filter(el => {
    const cs = window.getComputedStyle(el);
    return cs.borderRadius === '14px' && (cs.backgroundColor === 'rgb(13, 148, 136)' || cs.backgroundColor === 'rgba(0, 0, 0, 0.06)');
  });
}
const bubblesBefore = findBubbles();
const lastBubbleBefore = bubblesBefore[bubblesBefore.length - 1];
let wasNearBottom = true;
if (lastBubbleBefore) {
  const rect = lastBubbleBefore.getBoundingClientRect();
  wasNearBottom = rect.top < window.innerHeight - 40 && rect.bottom > 0;
}

const previous = variables['040a7bd6-1f18-4205-ae04-847f0221069d'] || [];
const previousMsgCount = previous.filter(i => i.type === 'message').length;

const raw = context.workflow['refresh_open_chat'].result || [];
const myId = localStorage.getItem('userId') || sessionStorage.getItem('userId') || '';
const todayKey = new Date().toDateString();
const y = new Date(); y.setDate(y.getDate() - 1);
const yesterdayKey = y.toDateString();
const items = [];
let lastDateKey = null;
raw.forEach(m => {
  const d = new Date(m.created_at);
  const dateKey = d.toDateString();
  if (dateKey !== lastDateKey) {
    const label = dateKey === todayKey ? 'Today' : (dateKey === yesterdayKey ? 'Yesterday' : d.toLocaleDateString());
    items.push({ type: 'divider', label, _dateKey: dateKey });
    lastDateKey = dateKey;
  }
  items.push({
    type: 'message',
    role: String(m.sender_id) === String(myId) ? 'me' : 'them',
    text: m.content,
    time: d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
    is_read: !!m.is_read,
    _dateKey: dateKey,
  });
});
for (let i = items.length - 1; i >= 0; i--) {
  if (items[i].type === 'message' && items[i].role === 'me') { items[i].isLastMine = true; break; }
}
const newCount = Math.max(0, items.filter(i => i.type === 'message').length - previousMsgCount);
variables['040a7bd6-1f18-4205-ae04-847f0221069d'] = items;

if (wasNearBottom) {
  variables['0e31f960-ce67-41d7-9b5d-a18d0c06b384'] = false;
  variables['a5b44b1e-a783-4e61-8b2c-34813fbaaa88'] = 0;
  setTimeout(() => {
    const bubbles = findBubbles();
    if (bubbles.length) bubbles[bubbles.length - 1].scrollIntoView({ block: 'end' });
  }, 200);
} else {
  variables['0e31f960-ce67-41d7-9b5d-a18d0c06b384'] = true;
  variables['a5b44b1e-a783-4e61-8b2c-34813fbaaa88'] = (variables['a5b44b1e-a783-4e61-8b2c-34813fbaaa88'] || 0) + newCount;
}

