let tries = 0;

function scrollToBottom() {
  const container = document.querySelector(
    '[data-ww-uid="a88c13ea-553f-4c01-a115-879d5d9a8662"]'
  );

  if (container) {
    container.scrollTo({
      top: container.scrollHeight,
      behavior: "smooth",
    });
    console.log("✅ Scrolled to bottom");
  } else if (tries < 10) {
    tries++;
    setTimeout(scrollToBottom, 300); // نحاول تاني كل 0.3 ثانية
  } else {
    console.log("❌ Container not found after 10 tries");
  }
}

